int main(void){
	string s,t;
	cin>>s;
	cin>>t;
	int n = min(s.size(),t.size());
	for(int i=0;i<n;i++){
		if(s[i]!=t[i]){
			cout<<(i+1)<<endl;
			return 0;
		}
	}
	if(s.size()!=t.size())cout<<(n+1)<<endl;
	else cout<<0<<endl;
	return 0;
}

